// Package api calls any endpoint of Discord's REST API, with the models of Discord's OpenAPI
// spec. models_gen.v and rest_gen.v are generated by tools/gen_api.vsh.
//
//   import veyfert.rest.api
//
//   mut discord := api.new(mut bot.rest)
//   guild := discord.get_guild(guild_id)!
//
// Calls share the client's rate limits. The shorters (`bot.messages`, `bot.members`...) cover
// the common endpoints with veyfert's own models and the cache; use this for the rest.
module api

import veyfert.rest

// Api holds the REST client its generated methods send requests with.
pub struct Api {
mut:
	http &rest.Rest = unsafe { nil }
}

// new wraps a REST client, usually `bot.rest`.
pub fn new(mut r rest.Rest) Api {
	return Api{
		http: &r
	}
}
